  function hash(s){let h1=2166136261,h2=2246822519;for(const c of normalize(s)){h1=Math.imul(h1^c.charCodeAt(0),16777619);h2=Math.imul(h2^c.charCodeAt(0),3266489917)}return (h1>>>0).toString(16).padStart(8,'0')+(h2>>>0).toString(16).padStart(8,'0')}
